UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Myxedema Coma Treatment: Step 2 — IV Levothyroxine (T4)","body":"**Myxedema coma (decompensated hypothyroidism): IV thyroid hormone treatment after stress-dose steroids.** [3][5]\n\n**[Levothyroxine](#/drug/levothyroxine/decompensated hypothyroidism) — mainstay of thyroid replacement:**\n\n**Loading dose:** 200-400 mcg IV\n• IBCC: 200 mcg for most patients (lower end preferred)\n• ATA guidelines: 200-400 mcg based on severity, age, body weight, cardiac history [5]\n• Use lower end (200 mcg) for: elderly, low body weight, coronary artery disease, arrhythmias\n\n**Maintenance:** 50-100 mcg IV daily (or 1.2 mcg/kg/day IV) [5]\n\n**Why IV?** GI absorption is unreliable in decompensated hypothyroidism (ileus, mucosal edema). Oral levothyroxine should NOT be used for initial treatment. Transition to PO (1.6 mcg/kg/day) once GI function restored. [3][5]\n\n**Safety note:** IV levothyroxine is safe to give empirically. T4 is the inactive pro-hormone — the normal circulating pool is ~1,000 mcg, so even if the diagnosis is wrong, 200-400 mcg won''t cause harm. [3]","citation":[3,5,14],"next":"thyroid-hypo-t3","treatment":{"firstLine":{"drug":"Levothyroxine","dose":"200-400 mcg IV load, then 50-100 mcg/day (or 1.2 mcg/kg/day)","route":"IV","frequency":"Daily","duration":"Until GI function restored, then transition to PO","notes":"Use lower end (200 mcg) for elderly, low body weight, CAD, arrhythmias. Transition to PO 1.6 mcg/kg/day when tolerating oral intake."},"monitoring":"TSH + fT4 every 1-2 days. TSH falls ~50%/week. fT4 should normalize within 4 days."},"summary":"Levothyroxine 200-400 mcg IV load — oral unreliable in decompensated state; safe to give empirically"}'::jsonb
